import { readFile, readdir, writeFile } from 'node:fs/promises';
import { gzipSync } from 'node:zlib';
const baseline=JSON.parse(await readFile('docs/bundle-baseline.json','utf8'));
const args = process.argv.slice(2);
if (args.length && (args.length !== 2 || args[0] !== '--out' || !args[1])) throw Error('Usage: node scripts/measure-bundle.mjs [--out <file>]');
const output = args[1] ?? 'docs/bundle-final.json';
const assets=await readdir('dist/assets');
const files=await Promise.all(assets.filter(file=>/\.(js|css|woff2|ttf)$/.test(file)).map(async file=>({file,gzip:gzipSync(await readFile(`dist/assets/${file}`)).length})));
const totalBytes=files.reduce((n,f)=>n+f.gzip,0);
const result={baselineCommit:baseline.commit,baselineBytes:baseline.totalBytes,totalBytes,deltaBytes:totalBytes-baseline.totalBytes,maxGrowthBytes:30000,files};
await writeFile(output,JSON.stringify(result,null,2)+'\n');console.log(result);
if(result.deltaBytes>result.maxGrowthBytes)throw Error('Bundle growth exceeds 30 KB gzip');
